-- S4-03 Batch 3 security fix: make rider assignment checks NULL-safe.
-- All signatures, lifecycle rules, POD requirements, events, and execution settings are preserved.

create or replace function public.rider_transition(p_order_id uuid,p_next public.delivery_status,p_idempotency_key text default null) returns public.orders language plpgsql security definer set search_path=public as $$declare o orders;old delivery_status;ok boolean;rid uuid;begin rid=current_rider_id();select * into o from orders where id=p_order_id for update;if o.id is null or rid is null or o.assigned_rider_id is distinct from rid then raise exception 'forbidden';end if;old=o.delivery_status;if old=p_next then return o;end if;ok=(old='created' and p_next='ready_for_pickup')or(old='ready_for_pickup' and p_next='picked_up')or(old='picked_up' and p_next='out_for_delivery')or(old='out_for_delivery' and p_next='arrived');if not ok then raise exception 'invalid transition % -> %',old,p_next;end if;update orders set delivery_status=p_next,updated_at=now() where id=o.id returning * into o;update delivery_stops set status=p_next,arrived_at=case when p_next='arrived' then now() else arrived_at end,updated_at=now() where order_id=o.id;insert into delivery_events(business_id,order_id,delivery_stop_id,assignment_id,event_type,from_status,to_status,actor_user_id,actor_role,metadata)select o.business_id,o.id,s.id,s.assignment_id,'delivery.status_changed',old,p_next,auth.uid(),'rider',jsonb_build_object('idempotency_key',p_idempotency_key) from delivery_stops s where s.order_id=o.id;return o;end$$;

create or replace function public.complete_delivery(p_order_id uuid,p_pod_path text,p_note text default '',p_idempotency_key text default null) returns public.orders language plpgsql security definer set search_path=public as $$declare o orders;rid uuid;begin rid=current_rider_id();select * into o from orders where id=p_order_id for update;if o.id is null or rid is null or o.assigned_rider_id is distinct from rid then raise exception 'forbidden';end if;if o.delivery_status='delivered' then return o;end if;if o.delivery_status<>'arrived' or nullif(trim(p_pod_path),'') is null then raise exception 'arrival and POD required';end if;update orders set delivery_status='delivered',completed_at=now(),updated_at=now() where id=o.id returning * into o;update delivery_stops set status='delivered',pod_storage_path=p_pod_path,pod_note=p_note,pod_captured_at=now(),pod_submitted_by=auth.uid(),completed_at=now(),updated_at=now() where order_id=o.id;insert into delivery_events(business_id,order_id,delivery_stop_id,assignment_id,event_type,from_status,to_status,actor_user_id,actor_role,metadata)select o.business_id,o.id,s.id,s.assignment_id,'delivery.completed','arrived','delivered',auth.uid(),'rider',jsonb_build_object('idempotency_key',p_idempotency_key) from delivery_stops s where s.order_id=o.id;return o;end$$;
